INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','set pen to paper','',NULL,'/set pen tuː ˈpeɪpər/','As soon as he set pen to paper, ideas came.','他一动笔,想法就涌来。','I couldn''t set pen to paper all day.','我一整天都写不出一个字。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','come to','',NULL,'/kʌm tuː/','The writer comes to discern hidden things.','作家渐渐辨认出隐藏的东西。','She came to love the quiet city.','她渐渐爱上了这座安静的城市。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','take comfort in','',NULL,'/teɪk ˈkʌmfərt ɪn/','He takes comfort in his own work.','他从自己的作品中得到慰藉。','We took comfort in her kind words.','她温暖的话语给了我们安慰。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l39','make order out of','',NULL,'/meɪk ˈɔːrdər aʊt ʌv/','A writer makes order out of the anarchy of his heart.','作家从内心的混沌中理出秩序。','She made order out of the chaos.','她把一团乱理出了头绪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"The writers ___ I respect confess they don''t know where they are going.\"(定语从句先行词指人、作宾语,填关系词)","options":["what","which","whom","whose"],"answer_index":2,"stem_cn":"我所敬重的那些作家,承认自己不知去向何方。","explanation_cn":"定语从句先行词指人、在从句里作宾语,用 whom。✓ the writers whom I respect. ✗ which(指物)/ whose(所有格)/ what(不引导定从):指人作宾语用 whom。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"He is a writer ___ everyone admires but few understand.\"(定语从句指人、作宾语,填关系词)","options":["whose","what","which","whom"],"answer_index":3,"stem_cn":"他是个人人钦佩、却少有人读懂的作家。","explanation_cn":"定语从句指人、作宾语,用 whom。✓ a writer whom everyone admires. ✗ which / whose / what:指人作宾语用 whom。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp1','choice','{"stem":"\"The reader for ___ he writes may never truly know him.\"(介词 + 关系代词,指人作宾语,填关系词)","options":["whom","who","that","which"],"answer_index":0,"stem_cn":"他为之写作的读者,也许永远不会真正了解他。","explanation_cn":"介词 + 关系代词,指人作宾语,介词后只能用 whom。✓ the reader for whom he writes. ✗ which / who(介词后不用 who)/ that(介词后不用 that):for + whom。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"___ the journey has begun, the destination often changes.\"(‘一旦…就…’,填时间连词)","options":["Because","Unless","Once","Although"],"answer_index":2,"stem_cn":"旅程一旦开始,目的地往往就变了。","explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun … ✗ Unless 除非 / Because 因为 / Although 虽然:‘一旦’用 Once。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"A story takes on a life of its own ___ the writer sets pen to paper.\"(‘一…就…’,填时间连词)","options":["unless","once","because","so"],"answer_index":1,"stem_cn":"作家一动笔,故事便有了自己的生命。","explanation_cn":"‘一…就…’用 once。✓ once the writer sets pen to paper. ✗ unless / because / so:‘一…就’用 once。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp2','choice','{"stem":"\"___ he has captured the image, he can rest at last.\"(‘一旦…’,填时间连词)","options":["Unless","Because","Once","Whether"],"answer_index":2,"stem_cn":"一旦捕捉到那个意象,他终于可以歇息。","explanation_cn":"‘一旦…’用 Once。✓ Once he has captured the image … ✗ Unless / Because / Whether:‘一旦’用 Once。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"A writer explaining his own book might as ___ try to explain a crime.\"(might as __ do,‘还不如/不妨’,填 as 后那个词)","options":["good","best","better","well"],"answer_index":3,"stem_cn":"作家解释自己的书,还不如去解释一桩罪案。","explanation_cn":"might as well do,‘还不如/不妨’;固定搭配填 well。✓ might as well try to explain a crime. ✗ good / better / best:此结构用 well。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"Since no one is listening, we might as well ___ home.\"(might as well + 动词原形,填原形)","options":["go","to go","went","going"],"answer_index":0,"stem_cn":"既然没人在听,我们不如回家。","explanation_cn":"might as well + 动词原形;填原形 go。✓ we might as well go home. ✗ going / went / to go:might as well 后接原形。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp3','choice','{"stem":"\"You might ___ well ask the wind to stop as ask him to explain his art.\"(‘做A无异于做B’这个结构,填 might 后紧跟的那个词)","options":["too","so","very","as"],"answer_index":3,"stem_cn":"让他解释自己的艺术,无异于让风停下。","explanation_cn":"‘做A无异于做B’= might as well A as B;填 might 后紧跟的那个词。✓ might as well ask the wind to stop as … ✗ so / too / very:此结构该位置用 as。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"The writer will not rest ___ he has captured the image.\"(‘直到…’,填时间连词)","options":["so","till","because","unless"],"answer_index":1,"stem_cn":"不捕捉到那个意象,作家便不肯歇息。","explanation_cn":"‘直到…’的时间连词是 till。✓ will not rest till he has captured it. ✗ unless 除非 / because 因为 / so 所以:‘直到’用 till。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"Do not judge the book until you ___ read the final draft.\"(until 从句用现在完成,填助动词)","options":["will","did","are","have"],"answer_index":3,"stem_cn":"读完终稿之前,别评判这本书。","explanation_cn":"until/till 从句表将来时用现在完成;填助动词 have。✓ until you have read the final draft. ✗ will(从句不用 will)/ are / did:现在完成用 have + 过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp4','choice','{"stem":"\"He kept rewriting till the story ___ found its true shape.\"(till 从句用现在完成,填助动词)","options":["will","had","is","does"],"answer_index":1,"stem_cn":"他不停重写,直到故事找到它真正的形状。","explanation_cn":"till 从句里跟随主句过去时,用过去完成;填助动词 had。✓ kept rewriting till the story had found its shape. ✗ will / is / does:此处用 had found。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"This organic process is ___ an indescribable fascination.\"(be __ + 抽象名词,相当于形容词,‘极其迷人’,填那个介词)","options":["at","in","of","for"],"answer_index":2,"stem_cn":"这一有机的过程,有着难以言说的魅力。","explanation_cn":"be of + 抽象名词 = 形容词;填介词 of。✓ is of an indescribable fascination(= fascinating). ✗ in / at / for:此结构用 of。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"His remark was of great ___ to every young writer.\"(be of + 抽象名词,‘很有价值’,填那个名词)","options":["valued","valuable","values","value"],"answer_index":3,"stem_cn":"他的话对每个年轻作家都极有价值。","explanation_cn":"be of + 抽象名词,‘很有价值’= of great value;填名词 value。✓ was of great value. ✗ valuable(形容词)/ valued / values:be of 后接名词 value。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp5','choice','{"stem":"\"A first draft is often of little ___ until it is remade.\"(be of + 抽象名词,‘没什么用’,填那个名词)","options":["used","useful","use","uses"],"answer_index":2,"stem_cn":"初稿在重写之前往往没什么用。","explanation_cn":"be of + 抽象名词,‘没什么用’= of little use;填名词 use。✓ of little use until it is remade. ✗ useful(形容词)/ used / uses:be of 后接名词 use。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"To admit something, especially reluctantly, is to ___ it.\"(“坦白,承认”用哪个词)","options":["confess","confuse","conceal","connect"],"answer_index":0,"stem_cn":"(尤指不情愿地)承认某事。","explanation_cn":"(尤指不情愿地)承认某事是 confess(坦白、承认)。✓ to admit reluctantly is to confess. ✗ conceal 隐瞒;✗ confuse 使糊涂;✗ connect 连接——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"A sudden brilliant idea that drives creative work is ___.\"(“灵感”用哪个词)","options":["isolation","imitation","inspiration","hesitation"],"answer_index":2,"stem_cn":"驱动创作的突发妙想。","explanation_cn":"驱动创作的突发妙想是 inspiration(灵感)。✓ a sudden brilliant idea is inspiration. ✗ imitation 模仿;✗ hesitation 犹豫;✗ isolation 孤立——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',5,'am4_l39_gp6','choice','{"stem":"\"To make out or perceive something with difficulty is to ___ it.\"(“看出,辨别”用哪个词)","options":["dismiss","discern","disturb","dissolve"],"answer_index":1,"stem_cn":"费力地看出或觉察到某物。","explanation_cn":"费力地看出或觉察到某物是 discern(看出、辨别)。✓ to perceive with difficulty is to discern. ✗ dismiss 打发;✗ disturb 打扰;✗ dissolve 溶解——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"confess 的意思是:","options":["隐瞒","坦白,承认","夸耀","否认"],"answer_index":1,"explanation_cn":"confess = 坦白、承认。✓ they confess at once."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"inspiration 的意思是:","options":["灵感","犹豫","模仿","疲惫"],"answer_index":0,"explanation_cn":"inspiration = 灵感。✓ that passes for inspiration."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"discern 的意思是:","options":["破坏","隐藏","看出,辨别","忽视"],"answer_index":2,"explanation_cn":"discern = 看出、辨别。✓ comes to discern things in his material."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"indescribable 的意思是:","options":["清晰的","难以形容的","短暂的","平凡的"],"answer_index":1,"explanation_cn":"indescribable = 难以形容的。✓ of an indescribable fascination."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"fathom 的意思是:","options":["编造","忘记","误解","彻底理解,看透"],"answer_index":3,"explanation_cn":"fathom = 彻底理解、看透。✓ cannot fathom the exact outline."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',6,NULL,'choice','{"stem":"pertinent 的意思是:","options":["中肯的,相关的","多余的","错误的","无关的"],"answer_index":0,"explanation_cn":"pertinent = 中肯的、相关的。✓ a pertinent observation."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 1 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":1,"options":["whom","which","whose","what"],"answer_index":0,"explanation_cn":"定语从句指人、作宾语,用 whom。✓ the writers whom I respect."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 2 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":2,"options":["Once","Unless","Because","Although"],"answer_index":0,"explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 3 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":3,"options":["well","good","better","best"],"answer_index":0,"explanation_cn":"might as well do,‘还不如’;固定搭配填 well。✓ might as well try to explain a crime."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',7,NULL,'cloze','{"stem":"第 4 空","context":"The writers ___1___ I respect confess they hardly know where they are going. ___2___ the journey has begun, the destination often changes. A writer explaining his own book might as ___3___ try to explain a crime. The whole process is ___4___ an indescribable fascination.","blank_no":4,"options":["of","in","at","for"],"answer_index":0,"explanation_cn":"be of + 抽象名词 = 形容词;填 of。✓ is of an indescribable fascination."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"How do professional writers ignore what they were taught at school about writing?","options":["They copy other writers","They never revise anything","They write only about school","They make no ''skeleton'' or plan, but discover the shape as they write"],"answer_index":3,"explanation_cn":"录音说:职业作家不搭学校教的‘骨架’,而是边写边发现作品的形状。✓ no skeleton, discover as they write."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"According to the writer, where does the real art of writing go?","options":["Into the drafts that follow the first one","Into reading one''s own books","Into pleasing the reader","Into the very first draft only"],"answer_index":0,"explanation_cn":"录音说:才华进初稿,艺术进其后的一稿又一稿。✓ art into the later drafts."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',8,NULL,'choice','{"stem":"Why is a writer who talks endlessly about his own books an ''unforgivable bore''?","options":["He hates his readers","Explaining his work is as pointless as explaining a crime or a love affair","He cannot write any more","He has nothing else to say"],"answer_index":1,"explanation_cn":"录音说:解释自己的作品和解释一桩罪案或一段情事一样徒劳,故成了讨厌鬼。✓ as pointless as explaining a crime."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"旅程一旦开始,目的地往往就变了\"(once 引导时间从句):","options":["As once the journey has begun, the destination often changes.","Once the journey will begin, the destination often changes.","Once the journey has begun, the destination often changes.","Once the journey has begun, but the destination often changes."],"answer_index":2,"explanation_cn":"once 引导时间从句,‘一旦…就…’;从句用现在完成 has begun、主句不再加 but(不写 Once…, but…)、once 前不加 As。✓ Once …, … 场合:说“一旦…就…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"作家解释自己的书,还不如去解释一桩罪案\"(might as well):","options":["A writer explaining his book might as well trying to explain a crime.","A writer explaining his book might as well try to explain a crime.","A writer explaining his book might well as try to explain a crime.","A writer explaining his book might as good try to explain a crime."],"answer_index":1,"explanation_cn":"might as well + 动词原形 try(不用 trying)、well 不写成 good、词序是 as well(不写 well as)。✓ might as well try … 场合:说“还不如/不妨做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',9,NULL,'choice','{"stem":"你想说\"这一有机的过程,有着难以言说的魅力\"(be of + 抽象名词):","options":["This organic process is of an indescribable fascination.","This organic process is with an indescribable fascination.","This organic process of an indescribable fascination is.","This organic process is an indescribable fascination of."],"answer_index":0,"explanation_cn":"be of + 抽象名词,‘极其迷人’;of 紧跟 be 之后(不后置)、不用 with 代替 of。✓ is of an indescribable fascination. 场合:说“(某物)具有某种性质”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"confess 的意思是:","options":["坦白,承认","隐瞒","否认","夸耀"],"answer_index":0,"explanation_cn":"confess = 坦白、承认。✓ they confess at once."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"inspiration 的意思是:","options":["犹豫","模仿","灵感","疲惫"],"answer_index":2,"explanation_cn":"inspiration = 灵感。✓ that passes for inspiration."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"The writers ___ I respect confess they don''t know where they are going.\"(定语从句指人、作宾语)","options":["whose","which","what","whom"],"answer_index":3,"stem_cn":"我所敬重的作家承认不知去向。","explanation_cn":"定语从句指人、作宾语,用 whom。✓ the writers whom I respect. ✗ which / whose / what。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"___ the journey has begun, the destination often changes.\"(‘一旦…就…’,时间连词)","options":["Because","Although","Once","Unless"],"answer_index":2,"stem_cn":"旅程一旦开始,目的地往往就变。","explanation_cn":"‘一旦…就…’的时间连词是 Once。✓ Once the journey has begun … ✗ Unless / Because / Although。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"set pen to paper\" 的意思是:","options":["撕掉纸","动笔,开始写作","朗读","收起笔"],"answer_index":1,"explanation_cn":"set pen to paper = 动笔、开始写作。✓ when they first set pen to paper."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"\"take comfort in\" 的意思是:","options":["从…中得到安慰","离开…","抱怨…","破坏…"],"answer_index":0,"explanation_cn":"take comfort in = 从…中得到安慰。✓ a crowd in which he may take comfort."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"According to the writer, what happens once a writer sets pen to paper?","options":["He copies what he learned at school","He stops after the first page","He follows a fixed ''skeleton'' to the end","He often makes radical changes of destination as the work grows"],"answer_index":3,"passage":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:作家一动笔,常随作品生长而彻底改变原定的方向。✓ radical changes of destination."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"Why can the wish to please the reader be a writer''s ''undoing''?","options":["He starts writing to please others instead of making order out of his own heart","Readers dislike being pleased","It wastes paper","It makes him famous too fast"],"answer_index":0,"passage":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:讨好读者之心会成为作家的败因,因为他转而为取悦别人而写,而非从内心的混沌中理出秩序。✓ writing to please, his undoing."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"What did a young writer observe about talent and art?","options":["Art comes first, then talent","Talent goes into the first draft, and art into the drafts that follow","Talent and art are the same thing","Neither matters at all"],"answer_index":1,"audio":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"录音里那位年轻作家说:才华用在初稿,艺术用在其后一稿又一稿。✓ talent first draft, art later."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l39',10,NULL,'choice','{"stem":"What kind of discipline does a real writer submit himself to?","options":["No discipline at all","Only the rules taught at school","A more ruthless discipline than any critic ever dreamed of","The judgment of the crowd"],"answer_index":2,"audio":"I have known very few writers, but those I have known — and whom I respect — confess at once that they have little idea where they are going when they first set pen to paper. They have a character in mind, perhaps two; they are in that state of eager discomfort that passes for inspiration; and all of them admit to radical changes of destination once the journey has begun. One, to my certain knowledge, spent nine months on a novel set in one distant country, then quietly moved the whole thing to another. I have never heard of anyone building the neat ''skeleton'' we were taught to make at school. In the breaking and remaking, in the timing and interweaving and beginning afresh, the writer comes to discern things in his own material that were not consciously in his mind when he began. This organic process, often leading to moments of extraordinary self-discovery, is of an indescribable fascination. A blurred image appears; he adds a brushstroke, and another, and it is gone; but something was there, and he will not rest till he has captured it. Sometimes the yeast within a writer outlives the book he has written. There are writers, I have heard, who read nothing but their own books; like adolescents before a mirror, they still cannot fathom the exact outline of the vision before them. For the same reason writers talk interminably about their own work, teasing out hidden meanings and laying new ones on top. A writer who does this is misunderstood — he might as well try to explain a crime, or a love affair — and he is, incidentally, an unforgivable bore. A young writer once made the pertinent observation that the talent goes into the first draft, and the art into the drafts that follow. For this reason too the writer, like any other artist, has no resting place, no crowd or movement in which he may take comfort, no judgment from outside that can replace the judgment from within. He makes order out of the anarchy of his own heart; he submits himself to a more ruthless discipline than any critic ever dreamed of; and when he flirts with fame, he is only taking time off from the search for what his world holds at its inmost point.","explanation_cn":"课文说:真正的作家让自己服从于比任何评论家所梦想的都更冷酷的纪律。✓ more ruthless than any critic."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
